CREATE TABLE t_p19850081_animal_dressup_game.costumes (id SERIAL PRIMARY KEY, player_id INTEGER REFERENCES t_p19850081_animal_dressup_game.players(id), animal_id INTEGER REFERENCES t_p19850081_animal_dressup_game.animals(id), name VARCHAR(200) NOT NULL, cloth_type VARCHAR(50) NOT NULL, material VARCHAR(50) NOT NULL, pattern_id INTEGER REFERENCES t_p19850081_animal_dressup_game.patterns(id), primary_color VARCHAR(20) NOT NULL, secondary_color VARCHAR(20) NOT NULL, is_public BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT NOW());